query:
PREFIX schema: <http://schema.org/>
PREFIX luc: <http://www.ontotext.com/connectors/lucene#>
PREFIX luc-index: <http://www.ontotext.com/connectors/lucene/instance#>
SELECT ?company ?name ?locality WHERE {
  ?search a luc-index:lindas_label ; luc:query "label:(schmid)" ;
          luc:limit "2000" ; luc:entities ?company .
  GRAPH <https://lindas.admin.ch/foj/zefix> { ?company a <https://schema.ld.admin.ch/ZefixOrganisation> ; schema:legalName ?name ;
          schema:address ?a . ?a schema:addressLocality ?locality }
} LIMIT 25
